-- Migração 4/4: palpites, resultados, jogos realizados e auditoria final
begin;
create temporary table mig_palp(id text,loteria text,email text,numeros jsonb,texto text,enviado_em timestamptz,status text,jogo integer) on commit drop;
insert into mig_palp values
('PALP-20260608160144-26242','Lotofacil Mensal 2026','portalsimonsports@gmail.com','[1,3,4,7,9,11,15,18,22,23]'::jsonb,'01-03-04-07-09-11-15-18-22-23','2026-06-08T16:01:44-03:00','ATIVO',1),('PALP-20260608183758-18342','Lotofacil Mensal 2026','portalsimonsports@gmail.com','[1,3,5,6,9,13,15,18,22,23]'::jsonb,'01 - 03 - 05 - 06 - 09 - 13 - 15 - 18 - 22 - 23','2026-06-08T18:37:58-03:00','ATIVO',1),('PALP-20260621222130-57702','Quina-de-Sao-Joao 2026','portalsimonsports@gmail.com','[2,8,18,25,33,47,54,56,68,79]'::jsonb,'02 - 08 - 18 - 25 - 33 - 47 - 54 - 56 - 68 - 79','2026-06-21T22:21:30-03:00','ATIVO',1),('PALP-20260712082919-54331','Lotofacil Julho 2026','portalsimonsports@gmail.com','[1,2,4,7,9,12,13,18,21,23]'::jsonb,'01 - 02 - 04 - 07 - 09 - 12 - 13 - 18 - 21 - 23','2026-07-12T08:29:19-03:00','ATIVO',1);
insert into public.palpites(bolao_id,usuario_id,numeros,texto_original,status,enviado_em,legacy_id,legacy_payload)
select b.id,u.id,s.numeros,s.texto,s.status,coalesce(s.enviado_em,now()),s.id,jsonb_build_object('fonte','PALPITES','jogo',s.jogo)
from mig_palp s join public.boloes b on b.loteria=s.loteria join public.usuarios u on lower(u.email)=lower(s.email)
where not exists(select 1 from public.palpites p where p.legacy_id=s.id);

create temporary table mig_result(bolao_id text,loteria text,concurso text,data_sorteio date,numeros jsonb,numeros_texto text) on commit drop;
insert into mig_result values
('ESP-1780183527018','Quina-de-Sao-Joao 2026','7051','2026-06-28','[19,32,50,73,75]'::jsonb,'19 - 32 - 50 - 73 - 75'),('ESP-1780229007322','Mega Sena 30 Anos 2026',null,'2026-05-24','[3,30,33,35,45,47]'::jsonb,'03-30-33-35-45-47');
insert into public.resultados(bolao_id,loteria,concurso,data_sorteio,numeros,numeros_texto,fonte,fonte_versao,legacy_payload)
select bolao_id,loteria,concurso,data_sorteio,numeros,numeros_texto,'GOOGLE_SHEETS','MIGRACAO_20260810',jsonb_build_object('fonte','EVENTOS_ESPECIAIS')
from mig_result s where not exists(select 1 from public.resultados r where r.bolao_id=s.bolao_id and coalesce(r.numeros_texto,'')=coalesce(s.numeros_texto,''));

