on conflict(legacy_file_id) do update set bolao_id=excluded.bolao_id,loteria=excluded.loteria,concurso=excluded.concurso,data_jogo=excluded.data_jogo,status=excluded.status,nome_arquivo=excluded.nome_arquivo,mime_type=excluded.mime_type,legacy_drive_url=excluded.legacy_drive_url,legacy_payload=excluded.legacy_payload;

insert into public.auditoria(entidade,entidade_id,acao,dados_depois,origem)
values('MIGRACAO','DB_BOLOES_ESPECIAIS','IMPORTACAO_INICIAL',
jsonb_build_object(
'usuarios',(select count(*) from public.usuarios),
'boloes',(select count(*) from public.boloes),
'participacoes',(select count(*) from public.participacoes),
'cotas',(select count(*) from public.cotas),
'pagamentos',(select count(*) from public.pagamentos),
'parcelas',(select count(*) from public.parcelas),
'comprovantes',(select count(*) from public.comprovantes),
'palpites',(select count(*) from public.palpites),
'resultados',(select count(*) from public.resultados),
'jogos_realizados',(select count(*) from public.jogos_realizados)
),'GOOGLE_SHEETS_SNAPSHOT_20260810');
commit;
